data.verdict:
{
  "causes": [
    {
      "cause": "First paint used the destination scope, but resolveGesture retained the root surface and disclosed sibling or primary data through mediated reads.",
      "earliest_signal": "The same entity produces destination-only first paint but root or sibling sentinel values in a gesture result.",
      "prevention": "Route both paths through context-selected law and bound resolution; exercise same-entity sentinels with real workers.",
      "interrogation_question": "Do gesture controls prove destination data positively while retaining distinct root and sibling values under the same lens and entity?"
    },
    {
      "cause": "Expanded children continued using readingResolversOf(gw), which currently searches gw.registered, despite gatherImpl selecting the bound registry.",
      "earliest_signal": "Container-local child schema expansion works but applies a root resolver or omits the container-only resolver.",
      "prevention": "Thread the bound fold into child resolver selection and use a distinctive child resolver output while preserving root lookup controls.",
      "interrogation_question": "Does the child test distinguish resolver execution from successful schema expansion?"
    },
    {
      "cause": "A forged kind tag or mutable caller binding changed the validated destination or selected root execution.",
      "earliest_signal": "A handcrafted context reaches a bundle getter, or changing the original binding changes subsequent reads.",
      "prevention": "Accept only factory-issued opaque contexts, freeze copied identity, and validate exact destination and inbox requester correspondence.",
      "interrogation_question": "Are both exported execution functions tested against forged contexts before bundle access and against input mutation after construction?"
    },
    {
      "cause": "Connection standing was checked only before an await, allowing revoked authority to finish admission or release rendered HTML.",
      "earliest_signal": "Signed revocation during admission resolves preparation successfully, or revocation during worker execution still returns HTML.",
      "prevention": "Check live standing before admission/render, after admission awaits, and after worker completion; retain real-worker positive and bystander controls.",
      "interrogation_question": "Do deterministic controls separately interrupt admission and rendering, and does final refusal still release acquired slots?"
    },
    {
      "cause": "Reusing a context retained valid-looking descendant and inbox state after an ancestor disappeared.",
      "earliest_signal": "A context continues preparing or rendering after a signed ancestor removal while the descendant declaration survives.",
      "prevention": "Use the shared live connectionStands check on every invocation and at asynchronous authority boundaries.",
      "interrogation_question": "Does ancestor removal leave the descendant and grant intact so it specifically tests the parent-chain requirement?"
    },
    {
      "cause": "Execution limits were taken from authority, snapshotted at context creation, or replaced by root defaults after the explicit execution envelope disappeared.",
      "earliest_signal": "A changed execution envelope does not affect the next admission/render, or loss of the envelope still starts a worker.",
      "prevention": "Resolve the execution gateway's envelope each call, preserve budget-keyed admission and shared slot accounting, and refuse missing envelopes.",
      "interrogation_question": "Do controls use distinct authority and execution gateways and verify budget changes, envelope loss, and slot release without claiming running-worker resizing?"
    },
    {
      "cause": "Probation framing followed the destination authority gateway instead of the explicitly selected execution gateway.",
      "earliest_signal": "HTML executed under a probationary pool lacks its frame because the destination is trusted.",
      "prevention": "Select probation state from execution and preserve the existing common framing path and confinement controls.",
      "interrogation_question": "Is there a positive case where authority and execution have different probation states and the returned frame follows execution?"
    },
    {
      "cause": "Unsupported bound history or write-capable binding shapes slipped through truthiness checks and reused root pin or pen behavior.",
      "earliest_signal": "asOf zero, a version-pinned binding, or a binding with only writable defined reaches bundle execution.",
      "prevention": "Refuse every defined bound asOf, version pin, pen, or writable field before bundle access or execution, using exact contextual refusal responses.",
      "interrogation_question": "Are malformed independent pen/writable shapes and zero-valued historical options covered as well as ordinary valid inputs?"
    },
    {
      "cause": "The root adapters changed route selection, admission refusal behavior, or historical/public discipline while moving into the common execution core.",
      "earliest_signal": "Unknown-route preparation rejects, channel routes use host execution limits, or public and historical responses differ from existing behavior.",
      "prevention": "Keep root and channel-pool selection in compatibility adapters and run the named root, historical, confinement, spawn, and probation controls against the shared core.",
      "interrogation_question": "Do the adapters preserve tolerant preparation and select the channel pool before creating its explicit root context?"
    },
    {
      "cause": "The context clock was captured once or omitted from bound resolution, causing reused contexts to evaluate stale time-sensitive data.",
      "earliest_signal": "Advancing now() between invocations leaves time-sensitive reads unchanged, or nonfinite time reaches a worker.",
      "prevention": "Sample now() per invocation, reject nonfinite values before execution, and pass the sampled wall-clock value consistently through first paint and mediated reads.",
      "interrogation_question": "Does a changing-clock control verify observable read evaluation rather than only counting calls to now()?"
    }
  ]
}
